import { NextResponse } from "next/server";
import { seed } from "@/lib/engine";

// Same shape as the FastAPI GET /analytics/content endpoint, served from
// the Gold seed data generated by pipeline/run_pipeline_local.py.
export async function GET() {
  return NextResponse.json({
    source: "gold_seed",
    catalog_items: seed.summary.contentItems,
    items: seed.contentAnalyticsByGenre,
  });
}
